def _feats(L, U, W):
    ce = of = ed = sw = 0
    for u in U:
        for l in L:
            if l[0] < u[0] and u[1] < l[1] and u[0] - l[0] == l[1] - u[1]: ce += 1
            if u[1] - u[0] == l[1] - l[0]:
                sw += 1
                if abs(u[0] - l[0]) == 1: of += 1
            if (u[0] == l[0]) != (u[1] == l[1]): ed += 1
    tw = set(L) & set(U)
    al = {b for a, b in L if b < W} & {b for a, b in U if b < W}
    st = al - {c for sp in tw for c in sp}
    return (len(tw), ce, of, ed, sw, len(al), len(st), len(U),
            len({b - a for a, b in U}), sum(1 for a, b in U if b - a == 2),
            max([b - a for a, b in tw], default=0))

def _all(W, cache={}):
    if W in cache: return cache[W]
    out = []
    def rec(x, acc):
        if x == W: out.append(acc); return
        for w in (2, 3, 4, 5, 6):
            if x + w <= W and W - x - w != 1: rec(x + w, acc + [(x, x + w)])
    rec(0, [])
    cache[W] = out
    return out

def solve(clue):
    rows = clue.split()
    N = int(rows[-1]); rows = rows[:-1]
